using System.Diagnostics;
using Microsoft.Extensions.AI;

namespace MyApp.Coach;

public sealed class CoachAgent
{
    private static readonly ActivitySource Source = new("MyApp.Coach");

    private readonly IChatClient _chat;

    public CoachAgent(IChatClient chat)
    {
        _chat = chat;
    }

    public async Task<string> RespondAsync(string userMessage, CancellationToken ct = default)
    {
        using var activity = Source.StartActivity("CoachRespond");
        activity?.SetTag("coach.input_length", userMessage.Length);

        var response = await _chat.GetResponseAsync(
            [
                new ChatMessage(ChatRole.System, "You are a supportive coach who helps people reach their goals."),
                new ChatMessage(ChatRole.User, userMessage)
            ],
            cancellationToken: ct);

        var text = response.Text ?? string.Empty;
        activity?.SetTag("coach.output_length", text.Length);
        return text;
    }
}

using System.Diagnostics;
using Microsoft.Extensions.DependencyInjection;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Coach;

public static class Telemetry
{
    public const string ServiceName = "MyApp.Coach";
    public static readonly ActivitySource ActivitySource = new(ServiceName);

    public static IServiceCollection AddCoachTelemetry(
        this IServiceCollection services,
        string? otlpEndpoint = null)
    {
        services.AddOpenTelemetry()
            .ConfigureResource(r => r.AddService(ServiceName))
            .WithTracing(builder =>
            {
                builder
                    .AddSource(ServiceName)
                    .AddSource("Microsoft.Extensions.AI");

                if (!string.IsNullOrEmpty(otlpEndpoint))
                {
                    builder.AddOtlpExporter(o => o.Endpoint = new Uri(otlpEndpoint));
                }
            });

        return services;
    }
}

