using System.Text.Json;
using Microsoft.Extensions.AI;
using MyApp.Coach;
using Xunit;

namespace MyApp.Eval;

/// <summary>
/// Runs comparison evaluations between baseline and candidate agent configurations.
/// Produces side-by-side outputs for each scenario to support manual or automated judging.
/// </summary>
public class CompareTests
{
    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };

    [Fact]
    public async Task Compare_BaselineAndCandidate_ProduceDifferentOutputs()
    {
        var scenarios = LoadScenarios("Scenarios/compare.json");

        var baselineClient = new StubChatClient("I hear you. That sounds really tough. Let's take this one step at a time.");
        var candidateClient = new StubChatClient("I understand this is difficult. Here's a concrete 3-step plan: 1) Update your resume today, 2) Reach out to your network this week, 3) Set a daily job-search routine.");

        var baselineAgent = new CoachAgent(baselineClient);
        var candidateAgent = new CoachAgent(candidateClient);

        var results = new List<CompareResult>();

        foreach (var scenario in scenarios)
        {
            var baselineResponse = await baselineAgent.RespondAsync(scenario.Input);
            var candidateResponse = await candidateAgent.RespondAsync(scenario.Input);

            results.Add(new CompareResult(
                scenario.Name,
                scenario.Input,
                baselineResponse,
                candidateResponse));

            // Both must produce non-empty responses
            Assert.False(string.IsNullOrWhiteSpace(baselineResponse));
            Assert.False(string.IsNullOrWhiteSpace(candidateResponse));
        }

        // Write comparison results for offline analysis
        var outputDir = Path.Combine(Directory.GetCurrentDirectory(), "results");
        Directory.CreateDirectory(outputDir);
        var outputPath = Path.Combine(outputDir, "comparison.json");
        await File.WriteAllTextAsync(outputPath, JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true }));
    }

    [Fact]
    public async Task Compare_BothVersions_MeetMinimumLengthRequirement()
    {
        var scenarios = LoadScenarios("Scenarios/compare.json");

        var baselineClient = new StubChatClient("Take things one step at a time. You've got this.");
        var candidateClient = new StubChatClient("Here's my detailed recommendation for your situation with specific action items and timeline.");

        var baselineAgent = new CoachAgent(baselineClient);
        var candidateAgent = new CoachAgent(candidateClient);

        foreach (var scenario in scenarios)
        {
            var baselineResponse = await baselineAgent.RespondAsync(scenario.Input);
            var candidateResponse = await candidateAgent.RespondAsync(scenario.Input);

            Assert.True(baselineResponse.Length >= 10, $"Baseline too short for '{scenario.Name}'");
            Assert.True(candidateResponse.Length >= 10, $"Candidate too short for '{scenario.Name}'");
        }
    }

    private static List<CompareScenario> LoadScenarios(string path)
    {
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<List<CompareScenario>>(json, JsonOptions)
            ?? throw new InvalidOperationException("Failed to load compare scenarios.");
    }

    private record CompareScenario(string Name, string Input, string? Context);
    private record CompareResult(string Scenario, string Input, string Baseline, string Candidate);
}

