using Microsoft.Extensions.AI;

namespace MyApp.Eval;

/// <summary>
/// A deterministic chat client for offline eval runs.
/// Returns a fixed response so tests validate wiring without requiring a live model.
/// </summary>
public sealed class StubChatClient : IChatClient
{
    private readonly string _response;

    public StubChatClient(string response)
    {
        _response = response;
    }

    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var responseMessage = new ChatMessage(ChatRole.Assistant, _response);
        return Task.FromResult(new ChatResponse(responseMessage));
    }

    public IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        throw new NotSupportedException("Streaming not supported in stub.");
    }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

